l, "is_oa": true, "landing_page_url": "https://surface.syr.edu/eecs_etd/307", "pdf_url": "https://surface.syr.edu/cgi/viewcontent.cgi?article=1311&context=eecs_etd", "source": {"id": "https://openalex.org/S4306401700", "display_name": "Syracuse University Libraries (Syracuse University)", "issn_l": null, "issn": null, "is_oa": false, "is_in_doaj": false, "is_core": false, "listed_in": [], "host_organization": "https://openalex.org/I70983195", "host_organization_name": "Syracuse University", "host_organization_lineage": ["https://openalex.org/I70983195"], "host_organization_lineage_names": [], "type": "repository"}, "license": null, "license_id": null, "version": "submittedVersion", "is_accepted": false, "is_published": false, "raw_source_name": "Electrical Engineering and Computer Science - Dissertations", "raw_type": "text"}, "abstract": "The vital essence of evolutionary learning consists of information flows between the environment and the entities differentially surviving and reproducing therein. Gain or loss of information in individuals and populations due to evolutionary steps should be considered in evolutionary algorithm theory and practice. Information theory has rarely been applied to evolutionary computation - a lacuna that this dissertation addresses, with an emphasis on objectively and explicitly evaluating the ensemble models implicit in evolutionary learning. Information theoretic functionals can provide objective, justifiable, general, computable, commensurate measures of fitness and diversity. We identify information transmission channels implicit in evolutionary learning. We define information distance metrics and indices for ensembles. We extend Price's Theorem to non-random mating, give it an effective fitness interpretation and decompose it to show the key factors influencing heritability and evolvability. We argue that heritability and evolvability of our information theoretic indicators are high. We illustrate use of our indices for reproductive and survival selection. We develop algorithms to estimate information theoretic quantities on mixed continuous and discrete data via the empirical copula and information dimension. We extend statistical resampling. We present experimental and real world application results: chaotic time series prediction; parity; complex continuous functions; industrial process control; and small sample social science data. We formalize conjectures regarding evolutionary learning and information geometry."}]", "excerpt_truncated": true, "source_sha256": "abb000c955159ed472f3f2c8e4f0c273d89b9103f1cc0a70f7db65b44e2a6c23", "verification_required": true, "topic_domain": "unassigned_inquiry", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.21203/rs.3.rs-10027334/v1", "openalex:W7214573681", "openalex:W2758179853"], "source_candidates": ["https://doi.org/10.21203/rs.3.rs-10027334/v1", "https://www.researchsquare.com/article/rs-10027334/latest.pdf", "https://surface.syr.edu/eecs_etd/307", "https://surface.syr.edu/cgi/viewcontent.cgi?article=1311&context=eecs_etd"], "source_candidate_identities": {}}
